// Complete OpenAPI 3.0.3 inventory of the Velo Finance API.
// Served by the backend at /docs (Swagger UI) and /openapi.json.
// Keep in sync with backend/server/routes.ts — every route below maps to a real handler.
// All authenticated routes expect `Authorization: Bearer <JWT>`; admin routes additionally
// require the ADMIN role and are issued only through the two-step admin login.

const bearer = [{ bearerAuth: [] }];

const healthPaths = {
  "/health": { get: { tags: ["Health"], summary: "Check API and database status", responses: { "200": { description: "Healthy (or database not configured — degraded but serving)" }, "503": { description: "Database unavailable" } } } },
  "/api/v1/platform/status": { get: { tags: ["Platform"], summary: "Public platform status (maintenance mode, announcements, banners, loan products summary)", responses: { "200": { description: "Platform status consumed by the frontend at boot" } } } },
  "/api/v1/platform/banners": { get: { tags: ["Platform"], summary: "Public marketing banner carousel", responses: { "200": { description: "Active banners with image data URLs and optional links" } } } },
  "/api/v1/public/loan-products": { get: { tags: ["Platform"], summary: "PUBLIC loan product catalog (no auth) — powers the landing-page calculator with the exact admin-configured terms", parameters: [{ name: "type", in: "query", schema: { type: "string", enum: ["PERSONAL", "BUSINESS"] }, description: "Returns the SINGLE authoritative product for that flow (same resolution as the borrower endpoint)" }, { name: "productId", in: "query", schema: { type: "string" }, description: "Returns one exact ACTIVE product" }], responses: { "200": { description: "Active loan products (each carries programType PERSONAL/BUSINESS/BOTH, limits, tenors, per-tenor monthly rates and fees). Served with Cache-Control: no-store" }, "404": { description: "productId not found or inactive" } } } },
  "/openapi.json": { get: { tags: ["Health"], summary: "This OpenAPI document", responses: { "200": { description: "OpenAPI 3.0.3 JSON" } } } }
};

