  "/api/v1/auth/admin/login": { post: { tags: ["Auth"], summary: "Step 1 of admin login — validate credentials and send an admin OTP", requestBody: { required: true, content: { "application/json": { schema: { type: "object", required: ["email", "password"], properties: { email: { type: "string", format: "email" }, password: { type: "string", format: "password" } } } } } }, responses: { "200": { description: "OTP challenge issued (challengeId returned)" }, "401": { description: "Invalid credentials" }, "403": { description: "Not an administrator" } } } },
