  "/api/v1/auth/password-reset/request": { post: { tags: ["Auth"], summary: "Request a customer password reset (email delivered)", requestBody: { required: true, content: { "application/json": { schema: { type: "object", required: ["email"], properties: { email: { type: "string", format: "email" } } } } } }, responses: { "200": { description: "Reset initiated" } } } },
